use serde_json::json;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let (cents, n) = match input {
        json::Number(n) => (n as i64, 0),
        json::String(s) => {
            let mut i = 0;
            let mut n = 0;
            while i < s.len() {
                let c = s.chars().nth(i).unwrap();
                let n = n * 10 + c.to_digit(10).unwrap() as i64;
                i += 1;
            }
            (n, 0)
        }
        _ => unreachable!(),
    };

    let mut shares = vec![0; n as usize];
    let mut i = 0;
    while i < shares.len() {
        shares[i] = (cents / (n as i64 - i)).max(1);
        cents %= (n as i64 - i);
        i += 1;
    }

    shares.sort_unstable();
    shares.dedup();

    let mut result = json!({});
    for i in 0..n {
        result = json!({
            "share": shares[i],
            "remainder": cents,
            "remaining": n - i,
        })
        .merge(result);
    }

    result
}
